module pll(input wire ref_clk, input wire reset, input wire [7:0] control_voltage, output reg out_clk);  
    reg [3:0] phase_error;  
    reg [7:0] vco_count;  

    always @(posedge ref_clk or posedge reset) begin  
        if (reset) begin  
            out_clk <= 0;  
            vco_count <= 0;  
        end else begin  
            // Simple phase detector: Assume phase_error is calculated  
            phase_error <= control_voltage[7:4] - vco_count[3:0];  
            // Update VCO based on the phase error  
            if (phase_error > 0) begin  
                vco_count <= vco_count + 1;  
            end else if (phase_error < 0) begin  
                vco_count <= vco_count - 1;  
            end  
            out_clk <= (vco_count[3:0] == 4'b1111) ? ~out_clk : out_clk;  
        end  
    end  
endmodule

