module watchdog_timer (  
    input clk,  
    input reset,  
    output reg timeout,  
    output reg clear  
);  
    parameter THRESHOLD = 20;  
    reg [4:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 0;  
            timeout <= 0;  
            clear <= 1;  
        end else begin  
            if (count < THRESHOLD) begin  
                count <= count + 1;  
                timeout <= 0;  
                clear <= 0;  
            end else begin  
                timeout <= 1;  
                clear <= 0;  
            end  
        end  
    end  
endmodule

