module sata_controller (
    input clk,
    input rst,
    input start,
    output reg [1:0] state // 00: IDLE, 01: TRAINING, 10: OPERATING
);
    parameter IDLE = 2'b00;
    parameter TRAINING = 2'b01;
    parameter OPERATING = 2'b10;

    reg [3:0] training_counter;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            training_counter <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= TRAINING;
                        training_counter <= 0;
                    end
                end
                TRAINING: begin
                    if (training_counter < 10) begin
                        training_counter <= training_counter + 1;
                    end else begin
                        state <= OPERATING;
                    end
                end
                OPERATING: begin
                    // Operating state remains until reset
                end
            endcase
        end
    end
endmodule

