module watchdog_timer #(
    parameter TIMEOUT = 10
)(
    input wire clk,
    input wire reset,
    input wire reset_signal,
    output reg timeout
);
    reg [3:0] counter; // Assuming a maximum of 15 clock cycles for simplicity

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            timeout <= 0;
        end else begin
            if (reset_signal) begin
                counter <= 0;
                timeout <= 0;
            end else if (counter < TIMEOUT) begin
                counter <= counter + 1;
            end

            if (counter == TIMEOUT - 1) begin
                timeout <= 1; // Signal timeout if counter reaches TIMEOUT
            end
        end
    end
endmodule

