module pitch_detector (
    input clk,
    input reset,
    input [7:0] signal_in,
    output reg pitch_detected
);
    parameter THRESHOLD = 100; // Set a frequency threshold
    reg [7:0] sample_buffer [0:4]; // Buffer to hold samples
    integer sample_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            sample_count <= 0;
            pitch_detected <= 0;
        end else begin
            // Shift samples into the buffer
            sample_buffer[sample_count] <= signal_in;
            sample_count <= sample_count + 1;

            // Detect pitch if we have enough samples
            if (sample_count == 5) begin
                pitch_detected <= (sample_buffer[0] > THRESHOLD) ||
                                  (sample_buffer[1] > THRESHOLD) ||
                                  (sample_buffer[2] > THRESHOLD) ||
                                  (sample_buffer[3] > THRESHOLD) ||
                                  (sample_buffer[4] > THRESHOLD);
                sample_count <= 0; // Reset sample count after detection
            end
        end
    end
endmodule

