module dma_controller(  
    input clk,  
    input reset,  
    input start,  
    input [7:0] source_addr,  
    input [7:0] dest_addr,  
    input [7:0] transfer_size,  
    output reg busy,  
    output reg [7:0] current_dest_addr  
);  
    reg [7:0] size;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            busy <= 0;  
            current_dest_addr <= 0;  
            size <= 0;  
        end else if (start && !busy) begin  
            busy <= 1;  
            current_dest_addr <= dest_addr;  
            size <= transfer_size;  
        end else if (busy) begin  
            if (size > 0) begin  
                current_dest_addr <= current_dest_addr + 1;  
                size <= size - 1;  
            end else begin  
                busy <= 0;  
            end  
        end  
    end  
endmodule

