module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    input wire [7:0] timeout_value,  
    output reg timeout  
);  
    reg [7:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            timeout <= 0;  
        end else begin  
            if (counter < timeout_value) begin  
                counter <= counter + 1;  
                timeout <= 0;  
            end else begin  
                timeout <= 1;  
            end  
        end  
    end  
endmodule

