module divider_4bit (
    input wire clk,
    input wire [3:0] dividend,
    input wire [3:0] divisor,
    output reg [3:0] quotient,
    output reg [3:0] remainder,
    input wire start,
    output reg done
);
    reg [3:0] count;
    reg [4:0] temp_dividend;
    reg [3:0] temp_divisor;
    reg state;

    parameter IDLE = 1'b0, DIVIDE = 1'b1;

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                if (start) begin
                    if (divisor == 4'b0000) begin
                        quotient <= 4'b0000;
                        remainder <= 4'b0000;
                    end else begin
                        temp_dividend <= {1'b0, dividend}; // Extend to 5 bits
                        temp_divisor <= divisor;
                        quotient <= 4'b0000;
                        remainder <= 4'b0000;
                        count <= 4'b0000;
                        state <= DIVIDE;
                    end
                    done <= 1'b0;
                end
            end
            DIVIDE: begin
                if (count < 4) begin
                    // Shift left
                    remainder <= {remainder[2:0], temp_dividend[4]};
                    temp_dividend <= {temp_dividend[3:0], 1'b0}; // Shift dividend left
                    count <= count + 1;

                    // Subtract divisor if possible
                    if (remainder >= temp_divisor) begin
                        remainder <= remainder - temp_divisor;
                        quotient[count] <= 1'b1;
                    end else begin
                        quotient[count] <= 1'b0;
                    end
                end else begin
                    state <= IDLE;
                    done <= 1'b1;
                end
            end
        endcase
    end
endmodule

