module turbo_encoder (
    input wire clk,
    input wire reset,
    input wire [4:0] data_in,
    output reg [6:0] encoded_out
);
    reg [2:0] state;
    reg [4:0] input_reg;

    // States
    localparam S_IDLE = 3'b000,
               S_LOAD = 3'b001,
               S_ENCODE = 3'b010,
               S_OUTPUT = 3'b011;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= S_IDLE;
            encoded_out <= 7'b0;
            input_reg <= 5'b0;
        end else begin
            case (state)
                S_IDLE: state <= S_LOAD;
                S_LOAD: begin
                    input_reg <= data_in;
                    state <= S_ENCODE;
                end
                S_ENCODE: begin
                    // Simple encoding logic (for example purposes)
                    encoded_out <= {input_reg[4:2], input_reg[1:0], input_reg[4] ^ input_reg[3]};
                    state <= S_OUTPUT;
                end
                S_OUTPUT: state <= S_IDLE;
            endcase
        end
    end
endmodule

