module WatchdogTimer(
    input wire clk,
    input wire reset,
    output reg timeout
);
    parameter TIMEOUT_PERIOD = 10; // Set a timeout period of 10 clock cycles
    reg [3:0] count; // 4-bit counter to count clock cycles

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            timeout <= 0;
        end else if (count >= TIMEOUT_PERIOD) begin
            timeout <= 1;
        end else begin
            count <= count + 1;
            timeout <= 0;
        end
    end
endmodule

