module encoder_8_to_3(  
    input [7:0] in,  
    output reg [2:0] out  
);  
    always @(*) begin  
        casez (in)  
            8'b00000001: out = 3'b000;  
            8'b0000001?: out = 3'b001;  
            8'b000001??: out = 3'b010;  
            8'b00001???: out = 3'b011;  
            8'b0001????: out = 3'b100;  
            8'b001?????: out = 3'b101;  
            8'b01??????: out = 3'b110;  
