module audio_sample_rate_converter #(
    parameter BUFFER_DEPTH = 16
)(
    input clk,
    input rst,
    input [15:0] data_in,
    input data_in_valid,
    output reg [15:0] data_out,
    output reg data_out_valid
);
    reg [15:0] fifo [0:BUFFER_DEPTH-1];
    reg [3:0] write_ptr;
    reg [3:0] read_ptr;
    reg [3:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            write_ptr <= 0;
            read_ptr <= 0;
            count <= 0;
            data_out_valid <= 0;
        end else begin
            if (data_in_valid && count < BUFFER_DEPTH) begin
                fifo[write_ptr] <= data_in;
                write_ptr <= write_ptr + 1;
                count <= count + 1;
            end

            if (count > 0) begin
                data_out <= fifo[read_ptr];
                data_out_valid <= 1;
                read_ptr <= read_ptr + 1;
                count <= count - 1;
                if (count == 1) begin
                    data_out_valid <= 0;
                end
            end
        end
    end
endmodule

