module PLL (
    input wire clk_ref,       // Reference clock input
    input wire rst,          // Reset signal
    output reg clk_out       // Output clock
);
    reg [1:0] state;        // State for the PLL
    reg [3:0] counter;      // Counter for frequency division

    // States
    localparam IDLE = 2'b00,
               LOCKED = 2'b01,
               UNLOCKED = 2'b10;

    // Frequency divider
    always @(posedge clk_ref or posedge rst) begin
        if (rst) begin
            counter <= 0;
            state <= IDLE;
            clk_out <= 0;
        end else begin
            counter <= counter + 1;
            if (counter == 4'd10) begin  // Divide by 10
                clk_out <= ~clk_out;
                counter <= 0;
            end
        end
    end

    // State machine for locking
    always @(posedge clk_ref or posedge rst) begin
        if (rst) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: state <= LOCKED;     // Transition to LOCKED state
                LOCKED: state <= LOCKED;   // Remain in LOCKED state
                UNLOCKED: state <= UNLOCKED;// Remain in UNLOCKED state
                default: state <= IDLE;
            endcase
        end
    end

endmodule

