module serializer_32bit(  
    input clk,  
    input reset,  
    input enable,  
    input [31:0] data_in,  
    output reg serialized_out,  
    output reg done  
);  
    reg [5:0] bit_index;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            bit_index <= 0;  
            serialized_out <= 0;  
            done <= 0;  
        end else if (enable) begin  
            if (bit_index < 32) begin  
                serialized_out <= data_in[bit_index];  
                bit_index <= bit_index + 1;  
                done <= 0;  
            end else begin  
                done <= 1;  
            end  
        end  
    end  
endmodule

