module crc_generator (
    input wire clk,
    input wire reset,
    input wire [3:0] data,
    input wire [3:0] polynomial,
    output reg [3:0] crc
);
    reg [3:0] shift_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            crc <= 4'b0000;
            shift_reg <= 4'b0000;
        end else begin
            shift_reg <= {shift_reg[2:0], data[0]};
            if (shift_reg[3] ^ data[0]) begin
                shift_reg <= shift_reg ^ polynomial;
            end
            crc <= shift_reg;
        end
    end
endmodule

