module DCT_2x2 (  
    input signed [7:0] pixel_00,  
    input signed [7:0] pixel_01,  
    input signed [7:0] pixel_10,  
    input signed [7:0] pixel_11,  
    output signed [7:0] dct_00,  
    output signed [7:0] dct_01,  
    output signed [7:0] dct_10,  
    output signed [7:0] dct_11  
);  
