module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    output reg timeout  
);  
    reg [2:0] counter; // 3-bit counter for 8 cycles  

    always @(posedge clk) begin  
        if (reset) begin  
            counter <= 3'b000;  
            timeout <= 1'b0;  
        end else begin  
            if (counter == 3'b111) begin // 8 cycles  
                timeout <= 1'b1;  
            end else begin  
                counter <= counter + 1;  
                timeout <= 1'b0;  
            end  
        end  
    end  
endmodule

