module sliding_window_protocol(  
    input clk,  
    input reset,  
    input [3:0] window_size,  
    input [3:0] ack,  
    output reg [3:0] packets_sent  
);  

    reg [3:0] current_packet;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            current_packet <= 0;  
            packets_sent <= 0;  
        end else begin  
            if (current_packet < window_size) begin  
                packets_sent <= current_packet;  
                current_packet <= current_packet + 1;  
            end else if (ack > 0) begin  
                current_packet <= current_packet - ack;  
            end  
        end  
    end  
endmodule

