module spi_controller(  
    input wire clk,  
    input wire rst_n,  
    input wire SCK,  
    input wire MOSI,  
    output reg [3:0] data_out,  
    output reg data_ready  
);  
    reg [2:0] bit_count;  
    reg [3:0] shift_reg;  

    always @(posedge SCK or negedge rst_n) begin  
        if (!rst_n) begin  
            bit_count <= 0;  
            shift_reg <= 0;  
            data_out <= 0;  
            data_ready <= 0;  
        end else begin  
            shift_reg <= {shift_reg[2:0], MOSI};  
            bit_count <= bit_count + 1;  
            if (bit_count == 3'd3) begin  
                data_out <= {shift_reg[2:0], MOSI};  
                data_ready <= 1;  
            end  
        end  
    end  

    always @(posedge clk) begin  
        if (data_ready) begin  
            data_ready <= 0;  
            bit_count <= 0;  
        end  
    end  
endmodule

module instruction_pipeline(clk, reset, instruction_in, instruction_out);  
    input clk, reset;  
    input [31:0] instruction_in;  
    output reg [31:0] instruction_out;  

    reg [31:0] IF_ID_reg;  
    reg [31:0] ID_EX_reg;  
    reg [31:0] EX_MEM_reg;  
    reg [31:0] MEM_WB_reg;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            IF_ID_reg <= 0;  
            ID_EX_reg <= 0;  
            EX_MEM_reg <= 0;  
            MEM_WB_reg <= 0;  
            instruction_out <= 0;  
        end else begin  
            // Pipeline logic  
            IF_ID_reg <= instruction_in;  
            ID_EX_reg <= IF_ID_reg;  
            EX_MEM_reg <= ID_EX_reg;  
            MEM_WB_reg <= EX_MEM_reg;  
            instruction_out <= MEM_WB_reg;  
        end  
    end  
endmodule

