module sr_flip_flop(
    input wire S,
    input wire R,
    input wire CLK,
    output reg Q,
    output reg Qn
);
    always @(posedge CLK) begin
        if (S && !R) begin
            Q <= 1'b1;
            Qn <= 1'b0;
        end else if (!S && R) begin
            Q <= 1'b0;
            Qn <= 1'b1;
        end
        // Keep the previous state if both S and R are low
        // If both S and R are high, the output state is undefined
    end
endmodule

