module viterbi_decoder(clk, rst, input_bits, decoded_bits);  
    input clk;  
    input rst;  
    input [3:0] input_bits; // Assuming input bits are 4 bits  
    output reg [3:0] decoded_bits; // 4 bits of decoded output  

    reg [3:0] state;  
    parameter IDLE = 4'b0000;  
    parameter S0 = 4'b0001;  
    parameter S1 = 4'b0010;  
    parameter S2 = 4'b0011;  
    parameter S3 = 4'b0100;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            decoded_bits <= 4'b0000;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (input_bits == 4'b0000) begin  
                        state <= S0;  
                        decoded_bits <= 4'b0001;  
                    end else if (input_bits == 4'b0001) begin  
                        state <= S1;  
                        decoded_bits <= 4'b0010;  
                    end  
                end  
                S0: begin  
                    state <= S2;  
                    decoded_bits <= 4'b0011;  
                end  
                S1: begin  
                    state <= S3;  
                    decoded_bits <= 4'b0100;  
                end  
                S2: begin  
                    state <= IDLE;  
                    decoded_bits <= 4'b0000;  
                end  
                S3: begin  
                    state <= IDLE;  
                    decoded_bits <= 4'b0001;  
                end  
                default: state <= IDLE;  
            endcase  
        end  
    end  
endmodule

