module watchdog_timer #(parameter TIMEOUT_VALUE = 10) (  
    input wire clk,  
    input wire reset,  
    input wire kick,  
    output reg timeout  
);  
    reg [3:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            timeout <= 0;  
        end else if (kick) begin  
            counter <= 0;  
            timeout <= 0;  
        end else begin  
            if (counter < TIMEOUT_VALUE)  
                counter <= counter + 1;  
            if (counter == TIMEOUT_VALUE)  
                timeout <= 1;  
        end  
    end  
endmodule

