module temp_shutdown (
    input clk,
    input rst,
    input [7:0] temperature,
    output reg shutdown
);
    parameter THRESHOLD_HIGH = 8'd75;
    parameter THRESHOLD_LOW = 8'd70;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            shutdown <= 0;
        end else begin
            if (temperature > THRESHOLD_HIGH) begin
                shutdown <= 1;
            end else if (temperature < THRESHOLD_LOW) begin
                shutdown <= 0;
            end
        end
    end
endmodule

