module temperature_sensor(
    input wire clk,
    input wire reset,
    input wire [7:0] temperature,
    output reg warning
);
    parameter THRESHOLD = 8'd75;
    reg [1:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            warning <= 0;
            state <= 2'b00;
        end else begin
            case (state)
                2'b00: begin
                    if (temperature > THRESHOLD) begin
                        warning <= 1;
                        state <= 2'b01;
                    end
                end
                2'b01: begin
                    if (temperature <= THRESHOLD) begin
                        warning <= 0;
                        state <= 2'b00;
                    end
                end
            endcase
        end
    end
endmodule

