module iir_filter (
    input clk,
    input rst,
    input signed [15:0] x,      // input sample
    output reg signed [15:0] y   // output sample
);
    reg signed [15:0] y1, y2;    // previous output samples

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y <= 0;
            y1 <= 0;
            y2 <= 0;
        end else begin
            y <= (0.1 * x) + (0.2 * y1) + (0.3 * y2) - (0.4 * y1) - (0.5 * y2);
            y2 <= y1;
            y1 <= y;
        end
    end
endmodule

module hmac(
    input wire clk,
    input wire reset,
    input wire [7:0] key,       // Fixed key for HMAC
    input wire [7:0] message,   // Input message
    output reg [7:0] hmac       // Output HMAC
);
    reg [7:0] hash;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            hmac <= 8'b0;
            hash <= 8'b0;
        end else begin
            // Simple hash function: parity
            hash <= message ^ key;  // XOR operation to generate hash
            hmac <= hash ^ key;     // Generate HMAC by XORing hash with key
        end
    end
endmodule

