module simple_nn_layer (
    input wire clk,
    input wire reset,
    input wire [7:0] input_data, // 8-bit input data
    input wire [7:0] weights,     // 8-bit weights
    input wire [7:0] bias,        // 8-bit bias
    output reg [15:0] output_data, // 16-bit output data (for overflow)
    output reg [7:0] weight_gradient, // Gradient for weights
    output reg [7:0] bias_gradient   // Gradient for bias
);

reg [15:0] sum; // For output calculation
reg [15:0] target; // Target output for calculating gradients

always @(posedge clk or posedge reset) begin
    if (reset) begin
        output_data <= 16'b0;
        weight_gradient <= 8'b0;
        bias_gradient <= 8'b0;
        sum <= 16'b0;
    end else begin
        // Forward Pass
        sum <= input_data * weights + bias;
        output_data <= sum;

        // Sample target value for gradient calculation, in a real scenario this would be an input
        target <= 16'd100; // Example target for gradient calculation

        // Backward Pass
        weight_gradient <= (output_data - target) * input_data; // dL/dw
        bias_gradient <= (output_data - target); // dL/db
    end
end

endmodule

